（2）计算实际风能和理论风能之比（利用率），以及图像 
clc,clear 
a=xlsread('C:\Users\Administrator\Desktop\第一问统计数据.xlsx','日平均实际输出功率
','B2:M32'); 
b=a(:); 
b([60:62 124 186 279 341],:)=[];%每天平均的实际功率 
b1=b'; 
x=1:365; 
plot(x,b1) 
xlabel('天数') 
ylabel('功率') 
hold on

31 
t=3600*x; 
t1=t(1);t2=t(end); 
pp=csape(t,b1); 
xsh=pp.coefs; 
TL=quadl(@(tt)fnval(pp,tt),t1,t2) %积分求总的储风量 
a1=xlsread('C:\Users\Administrator\Desktop\第一问统计数据.xlsx','日平均风速','B2:M32'); 
b2=a1(:); 
b2([60:62 124 186 279 341],:)=[]; 
b3=b2'; 
x=1:365; 
f=[]; 
for i=1:365 
 c=0.5.*0.9726.*b3(i).^3; %计算理论功率 
 f=[f c]; %每天理论理论功率 
end 
f; 
plot(x,f,'r-') 
legend('实际功率','理论功率') 
t3=3600*x; 
t4=t3(1);t5=t3(end); 
pp1=csape(t3,f); 
xsh1=pp1.coefs; 
TL1=quadl(@(tt1)fnval(pp1,tt1),t4,t5) %积分求理论总的储风量 
TL/TL1 %利用率 
